                if d-c>=1: segs.append(('h',r,c,d))
                c=d+1
            else: c+=1
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]==2:
                d=r
                while d+1<H and g[d+1][c]==2: d+=1
                if d-r>=1: segs.append(('v',c,r,d))
                r=d+1
            else: r+=1
    out=[r[:] for r in g]
    for (bx,bcy,bxr,bxc) in boxes:
        cy,cx=(bx+bxr)//2,(bcy+bxc)//2
        own=None
        for kind,pos,a,b in segs:
