            if kind=='v' and pos==cx and a<=cy<=b: own=('v',pos)
        # rays perpendicular to own line, both dirs, to border: paint 0->1, 2->1, 3 stays
        if own is None: continue
        dr,dc = (0,1) if own[0]=='v' else (1,0)
        for sgn in (1,-1):
            r,c=cy+sgn*dr,cx+sgn*dc
            while 0<=r<H and 0<=c<W:
                v=g[r][c]
                if v==3: break
                if v==2:
                    # own-line cell: skip painting
                    if own[1]!=c or (own[0]=='v' and own[1]!=r):
                        out[r][c]=1
                else:
                    out[r][c]=1
                r+=sgn*dr; c+=sgn*dc
        # other parallel lines: foot = projection of center; block or ring by direction
        for kind,pos,a,b in segs:
            if kind==own[0] and pos==own[1]: continue
            rr,cc = (pos,cx) if kind=='h' else (cy,pos)
            # direction from center to foot
            if kind=='v':
                dx= cx-pos
                filled = dx>0  # right -> filled block; left -> ring
