def solve(g,stop_at_line=False,blocks=True):
    O=[r[:] for r in g]; H,W=len(g),len(g[0])
    boxes=[]
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c]==2 and all(g[r+i][c+j]==3 for i in(-1,0,1) for j in(-1,0,1) if(i,j)!=(0,0)):
                boxes.append((r,c))
    # line cells: 2-cells not inside any box ring; a cell is "line" if it's part of a maximal run of 2s of len>=2? use: 2 not in any box
    def is_line(r,c): return g[r][c]==2 and (r,c) not in {(rr,cc) for rr,cc in boxes} and True
